// Baut den Tagesbericht aus VictoriaMetrics (ALERTS-Serie von vmalert) und der GitHub-API.
const cfg = $('Config').first().json;
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const since = Date.now() - 24 * 3600 * 1000;
const fmt = d => new Date(d).toLocaleString('de-DE', { timeZone: cfg.timezone, day: '2-digit', month: '2-digit', hour: '2-digit', minute: '2-digit' });
const dur = m => m >= 60 ? Math.floor(m / 60) + ' h ' + (m % 60) + ' min' : m + ' min';
const sev = s => ({ critical: '🔴', warning: '🟠' }[s] || '🔵');
const target = l => l.instance || l.pool || l.name || l.job || '';

// --- Alerts ---
const firingNow = ($('Alerts jetzt').first().json.data?.result) || [];
const fired24h = ($('Alerts 24h').first().json.data?.result) || [];
const key = l => [l.alertname, target(l)].join('|');
const nowKeys = new Set(firingNow.map(r => key(r.metric)));
const lines = ['<b>📋 Homelab-Tagesbericht ' + esc(new Date().toLocaleDateString('de-DE', { timeZone: cfg.timezone })) + '</b>', '', '<b>🚨 Alerts (24 h)</b>'];
if (!fired24h.length && !firingNow.length) {
  lines.push('✅ Keine Alerts.');
} else {
  const active = fired24h.filter(r => nowKeys.has(key(r.metric)));
  const resolved = fired24h.filter(r => !nowKeys.has(key(r.metric)));
  for (const r of firingNow.filter(r => !fired24h.some(f => key(f.metric) === key(r.metric)))) active.push({ metric: r.metric, value: [0, '1'] });
  if (active.length) {
    lines.push('Aktiv:');
    for (const r of active) lines.push(sev(r.metric.severity) + ' ' + esc(r.metric.alertname) + ' ' + esc(target(r.metric)) + ' (seit ≥ ' + dur(Number(r.value[1])) + ')');
  }
  if (resolved.length) {
    lines.push('Wieder gelöst:');
    for (const r of resolved) lines.push('✔️ ' + esc(r.metric.alertname) + ' ' + esc(target(r.metric)) + ' (' + dur(Number(r.value[1])) + ' aktiv)');
  }
}

// --- Renovate ---
const isBot = p => /renovate/i.test(p.user?.login || '');
const prLink = p => '<a href="' + p.html_url + '">#' + p.number + '</a> ' + esc(p.title.replace(/^chore\(deps\): update /, ''));
const open = ($('PRs offen').first().json.body || []).filter(isBot);
const merged = ($('PRs geschlossen').first().json.body || []).filter(p => isBot(p) && p.merged_at && Date.parse(p.merged_at) >= since);
const body = $('Dependency Dashboard').first().json.body || '';
const section = name => {
  const m = body.split(/^## /m).find(s => s.startsWith(name));
  return m ? m.split('\n').filter(l => /^ - \[ \] <!-- (approve|unschedule|retry|recreate)-branch/.test(l)).map(l => l.replace(/^ - \[ \] <!--.*?-->/, '').replace(/^chore\(deps\): update /, '')) : [];
};
const pending = section('Pending Approval');
const waiting = section('Awaiting Schedule');
const errored = [...section('Errored'), ...section('PR Creation Errored')];
const problems = (body.split(/^## /m).find(s => s.startsWith('Repository Problems')) || '').split('\n').filter(l => /^ - /.test(l)).map(l => l.replace(/^ - /, ''));
const run = ($('Renovate-Lauf').first().json.body?.workflow_runs || [])[0];

lines.push('', '<b>📦 Renovate</b>');
if (run) {
  const ok = run.conclusion === 'success';
  lines.push((ok ? '✅' : '❌') + ' Letzter Lauf: ' + fmt(run.created_at) + ' (<a href="' + run.html_url + '">' + esc(run.conclusion || run.status) + '</a>)' + (Date.parse(run.created_at) < since ? ' ⚠️ älter als 24 h' : ''));
}
lines.push('Gemergt (24 h): ' + merged.length);
for (const p of merged.slice(0, 10)) lines.push('• ' + prLink(p));
lines.push('Offene PRs: ' + open.length);
for (const p of open.slice(0, 10)) lines.push('• ' + prLink(p));
if (pending.length) { lines.push('Wartet auf deine Freigabe (Major): ' + pending.length); for (const t of pending) lines.push('• ' + esc(t)); }
if (waiting.length) lines.push('Wartet auf Zeitfenster: ' + waiting.length);
if (errored.length) { lines.push('❌ Fehler: ' + errored.length); for (const t of errored) lines.push('• ' + esc(t)); }
for (const t of problems) lines.push('⚠️ ' + esc(t.replace(/^⚠️\s*/, '')));
lines.push('<a href="https://github.com/' + cfg.repo + '/issues/' + cfg.dashboardIssue + '">Dependency Dashboard</a>');

let text = lines.join('\n');
if (text.length > 4000) text = text.slice(0, 3990) + '\n…';
return [{ json: { text } }];
